-- Already applied to the linked Supabase project by ChatGPT on 2026-08-07.
-- Kept here so the repository records the live schema.
alter table public.fixtures add column if not exists provider_updated_at timestamptz, add column if not exists odds_bookmaker text, add column if not exists last_synced_at timestamptz;
create unique index if not exists fixtures_provider_fixture_id_unique on public.fixtures(provider_fixture_id) where provider_fixture_id is not null;
create table if not exists public.fixture_import_runs (id uuid primary key default gen_random_uuid(), source text not null default 'api-football', trigger_source text not null check (trigger_source in ('cron','admin')), status text not null check (status in ('running','success','partial','failed')), started_at timestamptz not null default now(), completed_at timestamptz, requests_used integer not null default 0, requests_limit integer, requests_remaining integer, fixtures_added integer not null default 0, fixtures_updated integer not null default 0, odds_updated integer not null default 0, results_updated integer not null default 0, alerts_created integer not null default 0, details jsonb not null default '{}'::jsonb, error_message text);
create table if not exists public.admin_alerts (id uuid primary key default gen_random_uuid(), alert_type text not null, severity text not null default 'warning' check (severity in ('info','warning','critical')), title text not null, message text not null, fixture_id uuid references public.fixtures(id) on delete set null, gameweek_id uuid references public.gameweeks(id) on delete set null, prediction_id uuid references public.predictions(id) on delete set null, member_id uuid references public.profiles(id) on delete set null, details jsonb not null default '{}'::jsonb, resolved boolean not null default false, resolved_at timestamptz, resolved_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now());
